WITH p AS (SELECT DISTINCT id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.id_imovel='BA-2929701-3438EBE3EC1C4160B13A7DC99112E048' AND a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(a.id_imovel,'-','') ORDER BY a.data_extracao DESC)=1),mut AS (SELECT DISTINCT id_referencia_bacen,cpf,cnpj FROM `basedosdados.br_bcb_sicor.recurso_publico_mutuario` WHERE ano_emissao BETWEEN 2013 AND 2026) SELECT COUNT(DISTINCT COALESCE(NULLIF(mut.cpf,''),NULLIF(mut.cnpj,''))) mutuarios_recurso_publico_mutuario,COUNT(DISTINCT p.id_referencia_bacen) operacoes FROM p JOIN car USING(id_car_norm) JOIN mut USING(id_referencia_bacen)